package mcp

import (
	"net/http"
	"net/url"
)

// withHeaders returns an *http.Client that adds cfg.Headers to requests sent
// to the configured endpoint's origin. base may be nil (the SDK default
// client); it is returned unchanged when there are no headers to add.
//
// Configured headers never override a header the request already carries —
// those are generated by the SDK or the OAuth layer and must win — and are
// never attached to a request for a different origin, so a redirect or a
// legacy SSE endpoint event cannot carry them elsewhere. Redirects are not
// followed at all, matching authHTTPClient.
func withHeaders(base *http.Client, cfg ServerConfig) *http.Client {
	if len(cfg.Headers) == 0 {
		return base
	}
	u, err := url.Parse(cfg.URL)
	if err != nil {
		return base
	}
	rt := http.DefaultTransport
	if base != nil && base.Transport != nil {
		rt = base.Transport
	}
	return &http.Client{
		Transport: &headerRoundTripper{base: rt, origin: originOf(u), headers: cfg.Headers},
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}
}

type headerRoundTripper struct {
	base    http.RoundTripper
	origin  string
	headers map[string]string
}

func (t *headerRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	if originOf(req.URL) != t.origin {
		return t.base.RoundTrip(req)
	}
	r := req.Clone(req.Context())
	for k, v := range t.headers {
		if r.Header.Get(k) == "" {
			r.Header.Set(k, v)
		}
	}
	return t.base.RoundTrip(r)
}

// originOf returns scheme://host[:port] with the default port made explicit,
// so "https://example.com" and "https://example.com:443" compare equal.
func originOf(u *url.URL) string {
	port := u.Port()
	if port == "" {
		switch u.Scheme {
		case "https":
			port = "443"
		case "http":
			port = "80"
		}
	}
	return u.Scheme + "://" + u.Hostname() + ":" + port
}
